:root{
  --night:#0a0d07; --night-rgb:10,13,7;
  --grass:url('data:image/webp;base64,');
  --hero-h:max(100svh,560px);
  --ink:#16140F; --ink-soft:#55503F; --ink-faint:#8A8368;
  --paper:#F6F1E7; --sand:#E4D6B8;
  --forest:#1D1710; --forest-2:#271F14; --forest-3:#302719;
  --forest-text:#EDE6D3; --forest-text-soft:rgba(237,230,211,.72); --forest-text-faint:rgba(237,230,211,.5);
  --forest-line:rgba(230,222,199,.16);
  --gold:#C89B3C; --gold-soft:#DDBB78;
  --shadow:0 20px 60px -30px rgba(0,0,0,.6);
  --font-serif:'Bodoni Moda',Georgia,'Times New Roman',serif;
  --font-sans:'Karla',-apple-system,'Segoe UI',Roboto,sans-serif;
  box-sizing:border-box;
  padding-top:env(safe-area-inset-top,0px);
  padding-bottom:env(safe-area-inset-bottom,0px);
}
html{scroll-padding-top:64px; scroll-behavior:smooth;}
*,*::before,*::after{box-sizing:inherit; margin:0; padding:0;}
body{
  background-color:var(--night);
  background-image:
    url('data:image/svg+xml;utf8,<svg xmlns="http://www.w3.org/2000/svg" width="180" height="180"><filter id="n"><feTurbulence type="fractalNoise" baseFrequency="0.85" numOctaves="2" stitchTiles="stitch"/><feColorMatrix type="saturate" values="0"/></filter><rect width="100%" height="100%" filter="url(%23n)" opacity="0.35"/></svg>'),
    linear-gradient(180deg, #0a0d07 0%, #0a0d07 100%);
  background-repeat:repeat, no-repeat;
  background-size:180px 180px, 100% 100%;
  background-blend-mode:overlay, normal;
  color:var(--forest-text);
  font-family:var(--font-sans); font-size:16px; line-height:1.6;
  -webkit-font-smoothing:antialiased; overflow-x:hidden;
}
body.no-scroll{overflow:hidden;}
img,video{max-width:100%; display:block;}
button{font:inherit; color:inherit; background:none; border:none;}
a{color:inherit; text-decoration:none;}
.wrap{max-width:1180px; margin:0 auto; padding:0 40px;}
@media (max-width:760px){.wrap{padding:0 22px;}}
.eyebrow{font-family:var(--font-sans); font-size:.76rem; font-weight:700; letter-spacing:.22em; text-transform:uppercase;}

/* ---------- Entrance ---------- */
.entrance{
  position:fixed; inset:0; z-index:200; background:#0C0A07;
  display:flex; align-items:center; justify-content:center;
  transition:opacity 1.1s cubic-bezier(.4,0,.2,1), visibility 0s linear 1.1s;
}
.entrance::before{
  content:''; position:absolute; inset:0;
  background-image:url('data:image/jpeg;base64,');
  background-size:cover; background-position:center 30%;
  transform:scale(1.06); transition:transform 1.6s cubic-bezier(.2,.6,.2,1);
}
.entrance::after{
  content:''; position:absolute; inset:0;
  background:linear-gradient(180deg, rgba(12,10,7,.55) 0%, rgba(12,10,7,.35) 45%, rgba(12,10,7,.75) 100%);
}
.entrance-title{
  position:relative; z-index:1; text-align:center; color:var(--forest-text);
  font-family:var(--font-serif); font-weight:600; font-size:clamp(1.9rem,6vw,3.6rem);
  letter-spacing:-.01em; opacity:0; transform:translateY(10px);
  transition:opacity 1s ease .3s, transform 1s ease .3s;
  padding:0 24px;
}
.entrance.ready::before{transform:scale(1);}
.entrance.ready .entrance-title{opacity:1; transform:translateY(0);}
.entrance.leave{opacity:0; visibility:hidden;}
.entrance.skip{display:none;}
@media (prefers-reduced-motion:reduce){
  .entrance{transition:opacity .3s linear, visibility 0s linear .3s;}
  .entrance::before{transition:none; transform:none;}
  .entrance-title{transition:none; opacity:1; transform:none;}
}

/* ---------- Mini nav ---------- */
.mini-nav{
  position:fixed; top:0; left:0; right:0; z-index:60;
  padding-top:env(safe-area-inset-top,0px);
  transition:background .4s ease, border-color .4s ease;
  border-bottom:1px solid transparent;
}
.mini-nav::before{
  content:''; position:absolute; left:0; right:0; top:0; bottom:-26px; z-index:-1; pointer-events:none; opacity:0;
  background:linear-gradient(180deg, rgba(var(--night-rgb),.80) 0%, rgba(var(--night-rgb),.58) 55%, rgba(var(--night-rgb),0) 100%);
  -webkit-backdrop-filter:blur(10px); backdrop-filter:blur(10px);
  -webkit-mask-image:linear-gradient(180deg,#000 0%,#000 52%,transparent 100%); mask-image:linear-gradient(180deg,#000 0%,#000 52%,transparent 100%);
  transition:opacity .45s ease;
}
.mini-nav.solid::before{opacity:1;}
.mini-nav{isolation:isolate;}
.mini-nav-inner{
  max-width:1180px; margin:0 auto; padding:18px 40px; display:flex;
  align-items:center; justify-content:space-between; gap:20px;
}
@media (max-width:760px){.mini-nav-inner{padding:14px 22px;}}
.mini-nav-title{
  font-family:var(--font-serif); font-weight:600; font-size:1.14rem; letter-spacing:.01em; font-style:italic;
  color:#fff; white-space:nowrap; overflow:hidden; text-overflow:ellipsis;
}
.mini-nav-links{display:flex; align-items:center; gap:26px;}
.mini-nav-links a{
  font-size:.76rem; font-weight:700; letter-spacing:.14em; text-transform:uppercase;
  color:#fff; opacity:.86; transition:opacity .2s ease;
  padding-bottom:2px; border-bottom:1px solid transparent;
}
.mini-nav-links a:hover{opacity:1; border-color:currentColor;}
.owner-tag{
  font-size:.72rem; letter-spacing:.08em; text-transform:uppercase; opacity:.75;
  display:none; align-items:center; gap:8px;
}
body.can-edit .owner-tag{display:inline-flex;}
.owner-tag .signout{text-decoration:underline; cursor:pointer;}

/* ---------- Hero ---------- */
.hero{
  position:relative; height:100svh; min-height:560px; overflow:hidden;
  display:flex; align-items:center; justify-content:center;
}
.hero-bg{
  position:absolute; inset:0; z-index:-2; transform:none !important;
  background-image:url('data:image/jpeg;base64,');
  background-size:cover; background-position:50% 100%;
}
.hero-scrim{
  position:absolute; inset:0; z-index:-1;
  background:linear-gradient(180deg, rgba(18,13,6,.5) 0%, rgba(18,13,6,.06) 22%, rgba(var(--night-rgb),.08) 58%, rgba(var(--night-rgb),.20) 82%, rgba(var(--night-rgb),.28) 100%);
}
.hero-scrim::before{
  content:''; position:absolute; inset:0;
  background:radial-gradient(60% 55% at 50% 42%, rgba(20,14,6,.05), rgba(16,11,5,.42) 72%, rgba(14,10,5,.6) 100%);
  -webkit-mask-image:linear-gradient(180deg,#000 0%,#000 52%,transparent 90%); mask-image:linear-gradient(180deg,#000 0%,#000 52%,transparent 90%);
}
.hero-inner{
  position:relative; z-index:2; width:100%; text-align:center;
  padding:calc(80px + env(safe-area-inset-top,0px)) 40px calc(64px + env(safe-area-inset-bottom,0px));
  display:flex; flex-direction:column; align-items:center;
}
@media (max-width:760px){.hero-inner{padding:calc(70px + env(safe-area-inset-top,0px)) 22px 56px;}}
.hero-inner .eyebrow{
  color:#F3DDAA; text-shadow:0 1px 12px rgba(0,0,0,.45); margin-bottom:20px; display:flex; align-items:center; gap:14px;
}
.hero-inner .eyebrow::before, .hero-inner .eyebrow::after{content:''; width:26px; height:1px; background:currentColor; opacity:.7;}
.hero h1{
  font-family:var(--font-serif); font-weight:600; font-style:italic; color:#FBF7EE;
  font-size:clamp(2.7rem,7.6vw,5.8rem); line-height:.98; letter-spacing:-.01em;
  max-width:16ch; text-shadow:0 4px 40px rgba(0,0,0,.3);
}
.hero-sub{
  margin-top:24px; max-width:40ch; color:rgba(251,247,238,.86);
  font-size:1.04rem; line-height:1.6;
}
.hero-foot{
  margin-top:52px; display:flex; flex-direction:column; align-items:center; gap:24px;
}
.hero-links{display:flex; align-items:center; gap:18px;}
.hero-links a{
  text-shadow:0 1px 14px rgba(0,0,0,.6);
  font-size:.78rem; font-weight:700; letter-spacing:.16em; text-transform:uppercase; color:#F3ECDC;
  border-bottom:1px solid rgba(243,236,220,.4); padding-bottom:4px; transition:border-color .2s ease;
}
.hero-links a:hover{border-color:#F3ECDC;}
.hero-links .sep{color:rgba(243,236,220,.4); font-size:.8rem;}
.scroll-cue{
  display:flex; flex-direction:column; align-items:center; gap:10px; color:#F3ECDC; opacity:.7;
  font-size:.68rem; letter-spacing:.18em; text-transform:uppercase;
}
.scroll-cue .line{width:1px; height:30px; background:linear-gradient(180deg, currentColor, transparent);}
@media (max-width:640px){
  .scroll-cue{display:none;}
  .hero-bg{background-position:24% 100%;}
  main::before{background-position:24% 0 !important;}
  .mini-nav-title{display:none;}
  .mini-nav-inner{justify-content:center;}
  .mini-nav-links{gap:20px;}
  .mini-nav-links a{white-space:nowrap;}
}

/* ---------- Section shells ---------- */
.ed-section{padding:100px 0; position:relative;}
/* continuation of the hero grass: same scale/offset as .hero-bg (cover of a 2400x1350 photo), tile starts exactly at the hero's last row */
main{position:relative; --img-w:max(100vw, calc(var(--hero-h) * 2400 / 1350)); --pre:calc(var(--img-w) * 160 / 2400);}
main::before{
  content:''; position:absolute; top:calc(-1 * var(--pre)); left:0; right:0; z-index:0; pointer-events:none;
  height:min(calc(100% + var(--pre)), 2400px);
  background-image:var(--grass); background-repeat:no-repeat;
  background-position:50% 0;
  background-size:max(100%, calc(var(--hero-h) * 2400 / 1350)) auto;
  -webkit-mask-image:linear-gradient(180deg,transparent 0,#000 var(--pre)), linear-gradient(180deg,#000 calc(100% - 320px),transparent 100%);
  -webkit-mask-composite:source-in;
  mask-image:linear-gradient(180deg,transparent 0,#000 var(--pre)), linear-gradient(180deg,#000 calc(100% - 320px),transparent 100%);
  mask-composite:intersect;
}
.ed-section.tight{padding:76px 0;}
.ed-section + .ed-section{border-top:1px solid; border-image:linear-gradient(90deg, transparent, rgba(221,187,120,.28), transparent) 1;}
.ed-section.tight:not(#planned){position:relative;}
.ed-section .wrap{position:relative; z-index:1;}
@media (max-width:760px){.ed-section{padding:64px 0;}}
.section-head{margin-bottom:56px;}
.section-head h2{
  font-family:var(--font-serif); font-weight:600; font-style:italic; letter-spacing:-.005em;
  font-size:clamp(2rem,4.2vw,3rem); line-height:1.05;
}
.section-head p{margin-top:16px; max-width:52ch; color:var(--forest-text-soft); font-size:1rem;}

/* ---------- Entry row (shared by both categories) ---------- */
.entry-list{display:flex; flex-direction:column;}
.entry-row{
  display:grid; grid-template-columns:1fr; gap:26px;
  padding:40px 0; border-top:1px solid var(--forest-line);
}
.entry-list .entry-row:last-child{border-bottom:1px solid var(--forest-line);}
@media (min-width:820px){
  .entry-row{grid-template-columns:1fr 1fr; align-items:center; gap:56px;}
  .entry-row.no-media{grid-template-columns:1fr;}
}
.entry-text .entry-date{
  font-size:.78rem; letter-spacing:.14em; text-transform:uppercase; color:var(--gold-soft);
  display:block; margin-bottom:10px;
}
.entry-text h3{
  font-family:var(--font-serif); font-weight:600; font-style:italic;
  font-size:clamp(1.5rem,2.8vw,2.1rem); letter-spacing:-.005em; margin-bottom:14px;
}
.entry-text p{color:var(--forest-text-soft); max-width:56ch; font-size:.98rem; white-space:pre-line;}
.entry-controls{display:none; gap:10px; margin-top:20px;}
body.can-edit .entry-controls{display:flex;}
.ghost-icon{
  width:32px; height:32px; border-radius:50%; display:flex; align-items:center; justify-content:center;
  border:1px solid var(--forest-line); color:var(--forest-text-soft); opacity:.7; transition:opacity .2s ease, background .2s ease;
}
.ghost-icon:hover{opacity:1; background:var(--forest-3);}

.entry-media{min-width:0;}
.media-grid{display:grid; grid-template-columns:repeat(3,1fr); gap:8px;}
.media-grid.n1{grid-template-columns:1fr;}
.media-grid.n2{grid-template-columns:1fr 1fr;}
.media-thumb{
  aspect-ratio:1/1; overflow:hidden; border:1px solid var(--forest-line); background:var(--forest-2);
  cursor:pointer; position:relative;
}
.media-thumb img,.media-thumb video{width:100%; height:100%; object-fit:cover; transition:transform .4s ease;}
.media-thumb:hover img,.media-thumb:hover video{transform:scale(1.06);}
.media-thumb .play-badge{position:absolute; inset:0; display:flex; align-items:center; justify-content:center;}
.media-thumb .play-badge svg{width:30px; height:30px; color:#fff; filter:drop-shadow(0 2px 6px rgba(0,0,0,.5));}
.media-thumb .more-badge{
  position:absolute; inset:0; background:rgba(10,8,4,.6); color:#fff;
  display:flex; align-items:center; justify-content:center;
  font-family:var(--font-serif); font-size:1.2rem;
}

/* ---------- Empty state ---------- */
.ed-empty{padding:40px 0; color:var(--forest-text-faint); font-size:.98rem;}
.ed-empty .btn{margin-top:18px;}

/* ---------- Stats ---------- */
.stats-wrap{display:flex; gap:80px; flex-wrap:wrap; justify-content:center; text-align:center;}
.stat-big b{
  display:block; font-family:var(--font-serif); font-weight:600; font-style:italic; font-size:clamp(2.6rem,7vw,4.2rem); line-height:1;
}
.stat-big span{display:block; margin-top:10px; font-size:.76rem; letter-spacing:.2em; text-transform:uppercase; color:var(--forest-text-faint);}

/* ---------- Buttons ---------- */
.btn{
  display:inline-flex; align-items:center; gap:10px; font-size:.78rem; font-weight:700;
  letter-spacing:.12em; text-transform:uppercase; cursor:pointer; padding:13px 22px;
  border:1px solid var(--forest-text); border-radius:2px; transition:background .18s ease, color .18s ease;
  background:transparent; color:var(--forest-text);
}
.btn:hover{background:var(--forest-text); color:var(--forest);}
.btn-primary{background:var(--forest-text); color:var(--forest);}
.btn-primary:hover{background:var(--gold); border-color:var(--gold); color:var(--forest);}
.btn-ghost{border-color:var(--forest-line); color:var(--forest-text-soft);}

.fab{
  position:fixed; right:24px; bottom:calc(24px + env(safe-area-inset-bottom,0px)); z-index:40;
  display:none; align-items:center; gap:10px; background:var(--forest-text); color:var(--forest);
  border-radius:999px; padding:15px 22px 15px 18px; box-shadow:var(--shadow); font-size:.78rem;
  font-weight:700; letter-spacing:.1em; text-transform:uppercase; cursor:pointer;
}
body.can-edit .fab{display:inline-flex;}
.fab svg{width:18px; height:18px;}

/* ---------- Footer ---------- */
footer{position:relative; padding:70px 0 calc(46px + env(safe-area-inset-bottom,0px));}
footer::before{
  content:''; position:absolute; left:0; right:0; bottom:0; top:-720px; z-index:0; pointer-events:none;
  background-image:var(--grass); background-repeat:no-repeat; background-position:50% 100%; background-size:cover;
  -webkit-mask-image:linear-gradient(180deg,transparent 0%,rgba(0,0,0,.55) 30%,#000 55%); mask-image:linear-gradient(180deg,transparent 0%,rgba(0,0,0,.55) 30%,#000 55%);
}
footer .wrap{position:relative; z-index:1;}
footer .foot-top{display:flex; justify-content:space-between; align-items:flex-end; gap:24px; flex-wrap:wrap; margin-bottom:40px;}
footer .foot-title{font-family:var(--font-serif); font-style:italic; font-size:1.3rem; color:var(--forest-text);}
footer .foot-links{display:flex; gap:24px;}
footer .foot-links a{font-size:.76rem; letter-spacing:.14em; text-transform:uppercase; opacity:.75;}
footer .foot-links a:hover{opacity:1;}
footer .foot-bottom{border-top:1px solid var(--forest-line); padding-top:22px; font-size:.78rem; opacity:.55;}

/* ---------- Carousel ---------- */
.carousel{
  position:fixed; inset:0; background:rgba(6,5,3,.96); display:none;
  align-items:center; justify-content:center; z-index:100;
}
.carousel.open{display:flex;}
.carousel-stage{position:relative; width:100%; height:100%; display:flex; align-items:center; justify-content:center; padding:24px;}
.carousel-stage img,.carousel-stage video{max-width:100%; max-height:88vh; border-radius:2px;}
.carousel-close{
  position:absolute; top:calc(18px + env(safe-area-inset-top,0px)); right:18px; z-index:2;
  width:40px; height:40px; border-radius:50%; background:rgba(255,255,255,.14); color:#fff; font-size:1.1rem; cursor:pointer;
}
.carousel-arrow{
  position:absolute; top:50%; transform:translateY(-50%); z-index:2; width:48px; height:48px;
  border-radius:50%; background:rgba(255,255,255,.14); color:#fff; font-size:1.3rem; cursor:pointer;
  display:flex; align-items:center; justify-content:center;
}
.carousel-arrow:hover{background:rgba(255,255,255,.26);}
.carousel-arrow.prev{left:14px;} .carousel-arrow.next{right:14px;}
.carousel-counter{
  position:absolute; bottom:calc(18px + env(safe-area-inset-bottom,0px)); left:50%; transform:translateX(-50%);
  z-index:2; color:#fff; font-size:.82rem; background:rgba(255,255,255,.14); padding:5px 14px; border-radius:999px;
}
@media (max-width:560px){.carousel-arrow{width:40px; height:40px; font-size:1.1rem;} .carousel-arrow.prev{left:6px;} .carousel-arrow.next{right:6px;}}

/* ---------- Modal (light box over dark page) ---------- */
.modal-overlay{
  position:fixed; inset:0; background:rgba(6,5,3,.6); backdrop-filter:blur(2px);
  display:none; align-items:flex-start; justify-content:center; z-index:90;
  padding:min(6vh,50px) 16px 16px; overflow-y:auto;
}
.modal-overlay.open{display:flex;}
.modal{background:var(--paper); color:var(--ink); border-radius:4px; width:100%; max-width:560px; box-shadow:var(--shadow); padding:34px 32px 28px;}
.modal h2{font-family:var(--font-serif); font-weight:600; font-size:1.5rem; margin-bottom:22px;}
.field{margin-bottom:16px;}
.field label{display:block; font-size:.74rem; font-weight:700; letter-spacing:.1em; text-transform:uppercase; color:var(--ink-faint); margin-bottom:8px;}
.field input[type=text],.field input[type=url],.field input[type=date],.field textarea{
  width:100%; border:0; border-bottom:1px solid rgba(22,20,15,.16); border-radius:0; padding:9px 2px;
  font-family:var(--font-sans); font-size:.98rem; background:transparent; color:var(--ink);
}
.field input:focus,.field textarea:focus{outline:none; border-color:var(--ink);}
.field textarea{min-height:96px; resize:vertical; line-height:1.5;}
.cat-toggle{display:flex; gap:0; border:1px solid rgba(22,20,15,.16);}
.cat-toggle label{
  flex:1; display:flex; align-items:center; justify-content:center; gap:8px; padding:11px;
  cursor:pointer; font-size:.76rem; font-weight:700; letter-spacing:.08em; text-transform:uppercase; color:var(--ink-faint);
}
.cat-toggle label:first-child{border-right:1px solid rgba(22,20,15,.16);}
.cat-toggle input{accent-color:var(--ink); margin-right:2px;}
.cat-toggle label:has(input:checked){background:var(--ink); color:var(--paper);}
.media-input-row{display:flex; flex-wrap:wrap; gap:8px; margin-top:8px;}
.media-preview{position:relative; width:60px; height:60px; overflow:hidden; border:1px solid rgba(22,20,15,.16); background:var(--sand);}
.media-preview img,.media-preview video{width:100%; height:100%; object-fit:cover;}
.media-preview .tag{position:absolute; left:2px; bottom:2px; background:rgba(22,20,15,.75); color:#fff; font-size:.6rem; padding:1px 5px;}
.media-preview button{position:absolute; top:2px; right:2px; width:16px; height:16px; border-radius:50%; background:rgba(22,20,15,.75); color:#fff; font-size:.64rem;}
.file-btn{
  display:inline-flex; align-items:center; gap:8px; border:1px dashed rgba(22,20,15,.2);
  padding:9px 14px; font-size:.78rem; letter-spacing:.05em; color:var(--ink-soft); cursor:pointer;
}
.file-btn:hover{border-color:var(--ink); color:var(--ink);}
.field-hint{font-size:.78rem; color:var(--ink-faint); margin-top:8px;}
.link-row{display:flex; gap:8px; margin-top:10px;}
.link-row input{flex:1; border:0; border-bottom:1px solid rgba(22,20,15,.16); padding:9px 2px; background:transparent; font-size:.94rem;}
.upload-row{display:flex; align-items:center; gap:10px; margin-top:10px; font-size:.82rem; color:var(--ink-soft);}
.upload-spinner{width:14px; height:14px; border-radius:50%; border:2px solid rgba(22,20,15,.16); border-top-color:var(--ink); animation:spin .8s linear infinite; flex:none;}
@keyframes spin{to{transform:rotate(360deg);}}
.modal-actions{display:flex; justify-content:flex-end; gap:10px; margin-top:24px;}
.modal-msg{font-size:.84rem; margin-top:10px; min-height:1.2em;}
.modal-msg.error{color:#A8432E;}

/* ---------- Login overlay ---------- */
.login-overlay{
  position:fixed; inset:0; background:rgba(6,5,3,.6); backdrop-filter:blur(2px);
  display:none; align-items:center; justify-content:center; z-index:95; padding:20px;
}
.login-overlay.open{display:flex;}
.login-box{background:var(--paper); color:var(--ink); border-radius:4px; width:100%; max-width:340px; box-shadow:var(--shadow); padding:32px 28px;}
.login-box h2{font-family:var(--font-serif); font-weight:600; font-size:1.25rem; margin-bottom:8px;}
.login-box p{color:var(--ink-soft); font-size:.86rem; margin-bottom:20px;}
.login-box .field input{width:100%; border:0; border-bottom:1px solid rgba(22,20,15,.16); padding:9px 2px; background:transparent; font-size:.96rem;}
.login-actions{display:flex; justify-content:flex-end; gap:10px; margin-top:16px;}
.login-msg{font-size:.82rem; margin-top:10px; min-height:1.1em; color:#A8432E;}

/* ---------- Toast ---------- */
.toast{
  position:fixed; left:50%; bottom:calc(24px + env(safe-area-inset-bottom,0px)); transform:translate(-50%,12px);
  background:var(--forest-text); color:var(--forest); padding:11px 20px; border-radius:999px; font-size:.86rem;
  box-shadow:var(--shadow); z-index:100; opacity:0; pointer-events:none; transition:opacity .25s ease, transform .25s ease;
}
.toast.show{opacity:1; transform:translate(-50%,0);}

/* ---------- Reveal ---------- */
.reveal{opacity:0; transform:translateY(26px); transition:opacity .8s cubic-bezier(.2,.6,.2,1), transform .8s cubic-bezier(.2,.6,.2,1);}
.reveal.in{opacity:1; transform:translateY(0);}

/* ---------- Focus / motion ---------- */
a:focus-visible, button:focus-visible{outline:2px solid var(--gold); outline-offset:2px;}
@media (prefers-reduced-motion:reduce){
  *{transition-duration:.001ms !important; animation-duration:.001ms !important;}
  .reveal{opacity:1; transform:none;}
  .hero-bg{transform:none !important;}
  html{scroll-behavior:auto;}
}
.qm{font-size:1.3em; display:inline-block; line-height:0; vertical-align:-.03em;}
.section-head h2 .qm{font-size:1.08em;}
.entrance{animation:entranceFailsafe .01s linear 5s forwards;}
@keyframes entranceFailsafe{to{opacity:0; visibility:hidden; pointer-events:none;}}
.sr-only{position:absolute; width:1px; height:1px; padding:0; margin:-1px; overflow:hidden; clip:rect(0,0,0,0); white-space:nowrap; border:0;}
